/**
 * Stage 1 signal-level parity test.
 *
 * Compares the per-bar confluence factor set produced by the TypeScript
 * engine against the expected set generated by the Python engine.
 *
 * This is the strongest parity assertion in the suite: it compares the
 * actual strategy decision (which confluence factors are present on which
 * bar) rather than just the intermediate indicator values.
 */
import * as fs from 'fs';
import * as path from 'path';

import { CSVLoader } from '../src/data/CSVLoader';
import { findSRZones, isPriceAtZone } from '../src/indicators/supportResistance';
import { findFibRetracement, isPriceAtFibLevel } from '../src/indicators/fibonacci';
import { findTrendlines, getTrendlinePrice } from '../src/indicators/trendlines';
import { calculateATR } from '../src/indicators/atr';

const REPO_ROOT = path.resolve(__dirname, '..', '..');
const FIXTURE = path.join(REPO_ROOT, 'shared', 'fixtures', 'parity_15m.csv');
const EXPECTED = path.join(REPO_ROOT, 'shared', 'fixtures', 'parity_signals.json');

const SR_LOOKBACK = 100;
const FIB_LOOKBACK = 50;
const TRENDLINE_TOLERANCE_ATR = 0.3;
const ZONE_TOLERANCE_ATR = 0.5;

describe('Stage 1 parity: per-bar confluence signals', () => {
  const expected = JSON.parse(fs.readFileSync(EXPECTED, 'utf-8'));
  const candles = new CSVLoader().loadFromFile(FIXTURE);

  function confluenceBars(): any[] {
    const rows: any[] = [];

    for (let i = SR_LOOKBACK; i < candles.length; i++) {
      const window = candles.slice(Math.max(0, i - SR_LOOKBACK), i);
      if (window.length < 50) continue;

      // The pattern computes the ATR over the full decision window.
      const atr = calculateATR(candles.slice(0, i), 14);
      const tol = atr * ZONE_TOLERANCE_ATR;
      const price = window[window.length - 1].close;

      const factors: string[] = [];

      const zones = findSRZones(window.slice(-SR_LOOKBACK), atr, ZONE_TOLERANCE_ATR, 2);
      const srResult = isPriceAtZone(price, zones, tol);
      if (srResult.atZone && srResult.zoneType) {
        factors.push(`sr_${srResult.zoneType.toLowerCase()}`);
      }

      const fib = findFibRetracement(window, FIB_LOOKBACK);
      if (fib) {
        const fibResult = isPriceAtFibLevel(price, fib, tol);
        if (fibResult.atFib && fibResult.level) {
          factors.push(`fib_${Math.round(fibResult.level.ratio * 1000)}`);
        }
      }

      const trendlines = findTrendlines(window, atr, TRENDLINE_TOLERANCE_ATR);
      for (const tl of trendlines.slice(0, 3)) {
        if (Math.abs(price - getTrendlinePrice(tl, window.length - 1)) <= tol) {
          factors.push(`trendline_${tl.type.toLowerCase()}`);
          break;
        }
      }

      if (factors.length > 0) {
        rows.push({
          bar: i,
          ts: new Date(candles[i].timestamp).toISOString(),
          price: Math.round(price * 1e6) / 1e6,
          factors: factors.slice().sort(),
        });
      }
    }

    return rows;
  }

  it('produces exactly the same confluence bars as the Python engine', () => {
    const actual = confluenceBars();

    expect(actual.length).toBe(expected.length);
    expect(actual.length).toBeGreaterThan(0);

    for (let i = 0; i < expected.length; i++) {
      expect(actual[i].bar).toBe(expected[i].bar);
      expect(actual[i].ts).toBe(expected[i].ts);
      expect(actual[i].price).toBeCloseTo(expected[i].price, 6);
      expect(actual[i].factors).toEqual(expected[i].factors);
    }
  });

  it('detects at least one multi-factor confluence', () => {
    const actual = confluenceBars();
    const multi = actual.filter((r) => r.factors.length >= 2);
    expect(multi.length).toBeGreaterThan(0);
  });
});
